// @vitest-environment jsdom
import { createApp, h, nextTick, ref, type App } from 'vue'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import AttachmentBlock from './attachment-block.vue'
import Gallery from './media-gallery-lightbox.vue'
import type { AttachmentItem } from '@/store/chat-list'
const native = vi.hoisted(() => ({ original: vi.fn(), save: vi.fn() }))
vi.mock('@/lib/harmony-files', () => ({ originalBlob: native.original, saveOriginal: native.save }))
vi.mock('@/store/chat-list', () => ({ useChatStore: () => ({ currentBotId: 'bot-unused' }) }))
vi.mock('../composables/useMediaGallery', () => ({ resolveUrl: (att: AttachmentItem) => att.url || '' }))
vi.mock('@felinic/ui', () => ({ Skeleton: 'span', toast: { error: vi.fn() } }))
vi.mock('@/composables/useKeyboardCommand', () => ({ useKeyboardCommand: vi.fn() }))
vi.mock('vue-i18n', () => ({ useI18n: () => ({ t: (key: string) => key }) }))
let app: App | undefined
const src = '/bots/10000000-0000-4000-8000-000000000001/sessions/20000000-0000-4000-8000-000000000002/delegations/30000000-0000-4000-8000-000000000003/attachments/' + 'a'.repeat(64)
const attachment = { type: 'image', name: 'original.png', mime: 'image/png', content_hash: 'a'.repeat(64), bot_id: '10000000-0000-4000-8000-000000000001', url: src, metadata: { delegation_url: src } }
const settle = async () => { await Promise.resolve(); await nextTick(); await Promise.resolve(); await nextTick() }
beforeEach(() => {
 vi.clearAllMocks()
 Object.defineProperty(HTMLImageElement.prototype, 'decode', { configurable: true, value: vi.fn().mockResolvedValue(undefined) })
 vi.stubGlobal('requestAnimationFrame', (cb: FrameRequestCallback) => { cb(0); return 0 })
 vi.stubGlobal('fetch', vi.fn(() => { throw new Error('unexpected fallback') }))
 vi.spyOn(URL, 'createObjectURL').mockReturnValue('blob:verified-synthetic')
 vi.spyOn(URL, 'revokeObjectURL').mockImplementation(() => {})
})
afterEach(() => { app?.unmount(); app = undefined; document.body.replaceChildren(); vi.restoreAllMocks(); vi.unstubAllGlobals() })
function mount(render: () => ReturnType<typeof h>) {
 const host = document.createElement('div'); document.body.append(host)
 app = createApp({ render }); app.mount(host); return host
}
describe('phone verified original inaccessible presentation', () => {
 it.each(['attachment', 'content'] as const)('shows one inaccessible state for a rejected %s reader, preserving the scoped reference and not retrying', async variant => {
  native.original.mockRejectedValue(new Error('denied'))
  const items = ref([attachment]); const snapshot = JSON.stringify(attachment); const open = vi.fn()
  const host = mount(() => h(AttachmentBlock, { variant, onOpenMedia: open, block: { id: 1, type: 'attachments', attachments: items.value } }))
  await settle()
  expect(host.querySelector('[role="status"]')?.textContent).toContain('chat.attachmentUnavailable')
  expect(host.textContent).toContain('original.png'); expect(host.querySelector('img,button')).toBeNull()
  // Adding an unrelated original restarts this watcher, but must not re-read the denied identity.
  items.value = [attachment, { ...attachment, content_hash: 'b'.repeat(64), url: src + '-other' }]
  await settle()
  expect(native.original.mock.calls.filter(call => call[0].content_hash === attachment.content_hash)).toHaveLength(1)
  host.click(); expect(open).not.toHaveBeenCalled(); expect(native.save).not.toHaveBeenCalled()
  expect(fetch).not.toHaveBeenCalled(); expect(JSON.stringify(attachment)).toBe(snapshot)
  expect(native.original.mock.calls[0]![0].metadata.delegation_url).toBe(src)
 })
 it.each(['attachment', 'content'] as const)('retires a decoded Blob failure in the %s variant', async variant => {
  native.original.mockResolvedValue(new Blob(['synthetic'], { type: 'image/png' }))
  const items = ref([attachment]); const open = vi.fn(); const host = mount(() => h(AttachmentBlock, { variant, onOpenMedia: open, block: { id: 1, type: 'attachments', attachments: items.value } }))
  await settle(); expect(host.querySelector('img')?.getAttribute('src')).toBe('blob:verified-synthetic')
  host.querySelector('img')!.dispatchEvent(new Event('error')); await settle()
  expect(host.querySelector('img,button')).toBeNull(); expect(host.querySelectorAll('[role="status"]')).toHaveLength(1)
  host.click(); expect(open).not.toHaveBeenCalled(); expect(native.original).toHaveBeenCalledTimes(1)
  items.value = [attachment, { ...attachment, content_hash: 'b'.repeat(64) }]; await settle()
  expect(native.original.mock.calls.filter(call => call[0].content_hash === attachment.content_hash)).toHaveLength(1)
 })
 it('keeps a healthy verified preview and original scoped click destination', async () => {
  native.original.mockResolvedValue(new Blob(['synthetic'], { type: 'image/png' }))
  const open = vi.fn(); const host = mount(() => h(AttachmentBlock, { onOpenMedia: open, block: { id: 1, type: 'attachments', attachments: [attachment] } }))
  await settle(); host.querySelector('img')!.dispatchEvent(new Event('load')); await settle()
  host.querySelector('button')!.click(); expect(open).toHaveBeenCalledWith(src, expect.any(HTMLElement))
  expect(host.querySelector('[role="status"]')).toBeNull(); expect(fetch).not.toHaveBeenCalled()
 })
 it('does not display an obsolete aborted reader failure on its replacement', async () => {
  let reject!: (reason: Error) => void
  native.original.mockImplementationOnce(() => new Promise((_resolve, fail) => { reject = fail }))
  native.original.mockResolvedValue(new Blob(['synthetic'], { type: 'image/png' }))
  const items = ref([attachment]); const host = mount(() => h(AttachmentBlock, { block: { id: 1, type: 'attachments', attachments: items.value } }))
  await settle(); items.value = [{ ...attachment, content_hash: 'b'.repeat(64) }]; await settle(); reject(new Error('aborted')); await settle()
  expect(host.querySelector('[role="status"]')).toBeNull(); expect(host.querySelector('img')).not.toBeNull()
 })
 it.each(['read', 'decode', 'predecode'] as const)('retains an inaccessible gallery %s identity through navigation and reopen', async failure => {
  const reader = vi.fn().mockRejectedValue(new Error('denied'))
  if (failure !== 'read') reader.mockResolvedValue(new Blob(['synthetic']))
  if (failure === 'predecode') vi.mocked(HTMLImageElement.prototype.decode).mockRejectedValue(new Error('decode failed'))
  const index = ref<number | null>(0)
  const items = [{ src, type: 'image' as const, name: 'original.png', original: reader }, { src: 'data:image/png;base64,synthetic', type: 'image' as const, name: 'other.png' }]
  const snapshot = JSON.stringify(items)
  mount(() => h(Gallery, { items, openIndex: index.value, 'onUpdate:openIndex': value => { index.value = value } }))
  await settle()
  if (failure === 'decode') { document.querySelector('img')!.dispatchEvent(new Event('error')); await settle() }
  expect(document.querySelector('[role="dialog"] [role="status"]')?.textContent).toBe('chat.attachmentUnavailable')
  expect(document.querySelector('[role="dialog"] img')).toBeNull()
  index.value = 1; await settle(); expect(document.querySelector('img')?.getAttribute('src')).toBe(items[1]!.src)
  index.value = 0; await settle(); index.value = null; await settle(); index.value = 0; await settle()
  expect(document.querySelectorAll('[role="dialog"] [role="status"]')).toHaveLength(1)
  expect(reader).toHaveBeenCalledTimes(1); expect(JSON.stringify(items)).toBe(snapshot); expect(fetch).not.toHaveBeenCalled()
 })
})
